function bindUIEvents(){
  var byId = function(id){ return document.getElementById(id); };

  // มิเตอร์โควต้าดูฟรีรายวัน
  if (typeof updateQuotaMeters === 'function') { try { updateQuotaMeters(); } catch (_) {} }

  var lbtn = byId('lbtn');
  if(lbtn) lbtn.addEventListener('click', toggleLang);

  var modeButtons = [
    ['mn0', function(){ setMode(0); }],
    ['mn1', function(){ setMode(1); }],
    ['mn2', function(){ setMode(2); }]
  ];
  modeButtons.forEach(function(pair){
    var el = byId(pair[0]);
    if(el) el.addEventListener('click', pair[1]);
  });

  var actionButtons = [
    ['btn0', function(){ if(typeof window.validateForm === 'function' && !window.validateForm(0)) return; go0(); }],
    ['btn1', function(){ if(typeof window.validateForm === 'function' && !window.validateForm(1)) return; go1(); }],
    ['btn2', function(){ if(typeof window.validateForm === 'function' && !window.validateForm(2)) return; go2(); }]
  ];
  actionButtons.forEach(function(pair){
    var el = byId(pair[0]);
    if(el) el.addEventListener('click', pair[1]);
  });

  var dateInputs = [
    ['d0', function(){ chkBtn(0); }],
    ['d1a', function(){ chkBtn(1); }],
    ['d1b', function(){ chkBtn(1); }],
    ['d2', function(){ chkBtn(2); }]
  ];
  dateInputs.forEach(function(pair){
    var el = byId(pair[0]);
    if(el) el.addEventListener('change', pair[1]);
  });

  document.addEventListener('click', function(ev){
    var bar = ev.target.closest && ev.target.closest('.el-bar-item');
    if (bar) {
      bar.classList.toggle('open');
      return;
    }

    var act = ev.target.closest && ev.target.closest('[data-action]');
    if (!act) return;

    var action = act.getAttribute('data-action');
    if (action === 'save-image') {
      saveImage(act.getAttribute('data-target'), act.getAttribute('data-filename'), ev);
    } else if (action === 'reset-mode') {
      resetM(parseInt(act.getAttribute('data-mode'), 10));
    } else if (action === 'clear-mode') {
      clearM(parseInt(act.getAttribute('data-mode'), 10));
    } else if (action === 'quota-share') {
      // แชร์แลกโควต้า: ใช้ช่องทางแชร์จริงเท่านั้น (โบนัสให้ใน recordShare)
      if (typeof ShareViral !== 'undefined') {
        if (navigator.share && ShareViral.nativeShare) { ShareViral.nativeShare(); }
        else if (ShareViral.copyShareLink) { ShareViral.copyShareLink(); }
      }
    } else if (action === 'pack-open') {
      // เปิดซองดวงรายเดือน
      if (typeof MemberHub !== 'undefined' && MemberHub.claimPack) { MemberHub.claimPack(); }
      if (typeof announce === 'function') { announce('เปิดซองดวงแล้ว'); }
    } else if (action === 'pack-share') {
      // อวดไพ่: รวมเป็นการ์ดเดียวแล้วแชร์/โหลด (นับโควต้าแชร์ให้ด้วย)
      if (typeof MemberHub !== 'undefined' && MemberHub.sharePack) { MemberHub.sharePack(); }
      if (typeof ShareViral !== 'undefined' && ShareViral.recordShare) { try { ShareViral.recordShare('pack'); } catch (_) {} }
    } else if (action === 'open-payment' || action === 'unlock-premium') {
      openPayment();
    } else if (action === 'close-payment') {
      closePayment();
    } else if (action === 'verify-pin') {
      verifyPin();
    }
  });
}

if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', bindUIEvents);
} else {
  bindUIEvents();
}

// ===== Form State Persistence (Quick Win #3) =====
// Save user input across page refreshes & mode switches
(function(){
  var KEY = "starvia_form_state_v1";
  var MODE_KEY = "starvia_active_mode_v1";
  // Field IDs to persist (3 modes)
  var FIELDS = [
    "n0","g0","d0","t0",
    "n1a","g1a","d1a","t1a",
    "n1b","g1b","d1b","t1b",
    "n2","g2x","d2"
  ];

  function readState(){
    var s = {};
    for(var i=0;i<FIELDS.length;i++){
      var el = document.getElementById(FIELDS[i]);
      if(el && el.value) s[FIELDS[i]] = el.value;
    }
    return s;
  }

  function writeState(s){
    try {
      localStorage.setItem(KEY, JSON.stringify(s));
    } catch(e){ /* quota or disabled - silent fail */ }
  }

  function save(){
    writeState(readState());
  }

  function restore(){
    try {
      var raw = localStorage.getItem(KEY);
      if(!raw) return;
      var s = JSON.parse(raw);
      for(var k in s){
        var el = document.getElementById(k);
        if(el && !el.value) el.value = s[k];
      }
      // Trigger button-enable check
      if(typeof chkBtn === "function"){
        try { chkBtn(0); chkBtn(1); chkBtn(2); } catch(_){}
      }
    } catch(e){}
  }

  function saveMode(m){
    try { localStorage.setItem(MODE_KEY, String(m)); } catch(_){}
  }

  function restoreMode(){
    try {
      var m = localStorage.getItem(MODE_KEY);
      if(m !== null && typeof setMode === "function"){
        setMode(parseInt(m, 10));
      }
    } catch(_){}
  }

  // Public API: window.StarviaForm
  window.StarviaForm = { save: save, restore: restore, clear: function(){
    try { localStorage.removeItem(KEY); } catch(_){}
  }, saveMode: saveMode, restoreMode: restoreMode };

  // Hook into setMode to save active mode
  if(typeof setMode === "function"){
    var _orig = setMode;
    setMode = function(m){
      _orig(m);
      saveMode(m);
    };
  }

  // Listen to all form changes
  function attach(){
    for(var i=0;i<FIELDS.length;i++){
      var el = document.getElementById(FIELDS[i]);
      if(!el) continue;
      el.addEventListener("input", save);
      el.addEventListener("change", save);
    }
  }

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", function(){ attach(); restore(); restoreMode(); });
  } else {
    attach(); restore(); restoreMode();
  }
})();

// ===== Scroll-Triggered Reveal =====
(function(){
  if(!('IntersectionObserver' in window)) {
    // Fallback: just show everything
    document.querySelectorAll('.reveal').forEach(function(el){ el.classList.add('in-view'); });
    return;
  }
  var obs = new IntersectionObserver(function(entries){
    for(var i=0;i<entries.length;i++){
      if(entries[i].isIntersecting){
        entries[i].target.classList.add('in-view');
        obs.unobserve(entries[i].target);
      }
    }
  }, { threshold: 0.12 });
  // Expose observer globally so report renderers can add new elements
  window._revealObserver = obs;
  document.querySelectorAll('.reveal').forEach(function(el){ obs.observe(el); });
})();

// ===== Form Validation Feedback =====
// Adds visual error states to required fields when user clicks submit
(function(){
  function clearError(el){
    el.classList.remove('form-error');
    var msg = el.parentNode.querySelector('.form-error-msg');
    if(msg) msg.remove();
  }

  function showError(el, msg){
    el.classList.add('form-error');
    if(!el.parentNode.querySelector('.form-error-msg')){
      var span = document.createElement('span');
      span.className = 'form-error-msg';
      span.textContent = msg;
      el.parentNode.appendChild(span);
    }
  }

  // Attach clear-on-input to all required fields
  var requiredFields = [
    {id:'d0',  msg:'กรุณาวันเกิด'},
    {id:'d1a', msg:'กรุณาวันเกิด'},
    {id:'d2',  msg:'กรุณาวันเกิด'}
  ];

  function attachClear(){
    requiredFields.forEach(function(f){
      var el = document.getElementById(f.id);
      if(!el) return;
      el.addEventListener('input', function(){ clearError(el); });
      el.addEventListener('change', function(){ clearError(el); });
    });
  }

  // Wrap the go functions with validation
  function validateAndRun(mode){
    var valid = true;
    if(mode === 0){
      var d0 = document.getElementById('d0');
      if(!d0.value){ showError(d0, 'กรุณาวันเกิด'); valid = false; }
    }
    if(mode === 1){
      var d1a = document.getElementById('d1a');
      if(!d1a.value){ showError(d1a, 'กรุณาวันเกิด'); valid = false; }
    }
    if(mode === 2){
      var d2 = document.getElementById('d2');
      if(!d2.value){ showError(d2, 'กรุณาวันเกิด'); valid = false; }
    }
    return valid;
  }

  // Expose validate for go0/go1/go2 to call
  window.validateForm = validateAndRun;

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', attachClear);
  } else {
    attachClear();
  }
})();
